"use client";

import { createContext, useContext } from "react";

/**
 * How a field row lays out its label against its control.
 *
 * `"flexible"` is the responsive one: stacked, then label-beside-control once the field row itself
 * is past the container `md` breakpoint. It is what you get by leaving `fieldDirection` unset — and
 * it is assignable so you can ask for it back where something else defaults you away from it, most
 * notably a `FormRenderer` drawer, which pins `"vertical"`.
 */
export type FieldDirection = "horizontal" | "vertical" | "flexible";

/** Loading flag — drives the Submit spinner and disables inputs. */
export const LoadingContext = createContext<boolean>(false);
export const useLoading = () => useContext(LoadingContext);

/**
 * The `<form>`'s `id`. Provided by the FormBuilder root so a `FormBuilder.Submit` rendered
 * **outside** the `<form>` element — the absolute header's action pill, or the drawer header —
 * can still submit it via native `form={id}` association without the caller wiring an id by hand.
 */
export const FormIdContext = createContext<string | undefined>(undefined);
export const useFormId = () => useContext(FormIdContext);

/**
 * Field row direction — set via `FormBuilder`'s `fieldDirection` prop. `undefined` (the default)
 * means "don't force one": `FieldSection` then uses its own responsive `flexible` layout, which
 * stacks on small screens and goes two-column at `lg`. Only set this to pin a direction.
 */
export const DirectionContext = createContext<FieldDirection | undefined>(undefined);
export const useDirection = () => useContext(DirectionContext);

/**
 * Field chrome mode — how much layout a field draws around its control.
 *
 * - `false` (the default) — the full `FieldSection` row: label, required marker, stacked hint.
 * - `"table"` — a `FormBuilder.Table` cell: no row chrome, errors as a tooltip on the control,
 *   and the control takes the flush table border treatment via `onTable`.
 * - `"bare"` — chrome-less anywhere else, e.g. a `DataViews` filter or config panel: no row and
 *   no stacked hint, but the control keeps its normal standalone border.
 *
 * The two chrome-less modes are deliberately distinct: dropping the label row and taking the
 * table border are different decisions, and only a real table cell wants both.
 */
export type CellMode = "table" | "bare" | false;

export const CellContext = createContext<CellMode>(false);

/** The raw mode. Prefer `useBare` / `useOnTable` — they express the two real questions. */
export const useCellMode = () => useContext(CellContext);
/** True when the field renders without `FieldSection` chrome — `"table"` **or** `"bare"`. */
export const useBare = () => useContext(CellContext) !== false;
/** True only inside a `FormBuilder.Table` cell — drives the control's `onTable` border style. */
export const useOnTable = () => useContext(CellContext) === "table";

/**
 * The "(Required)" tag `FieldShell` prints beside a `required` field's label.
 *
 * LOCAL PATCH (Contact Center): upstream hardcodes the English literal, so a
 * localized app cannot translate it. Defaulting to that literal keeps every
 * existing caller identical; provide the context once near the app root to
 * localize every field at once. Logged in TORCH-GLARE-FEEDBACK.md — re-apply
 * after any `npx torch-glare update`.
 */
export const RequiredLabelContext = createContext<string>("(Required)");
export const useRequiredLabel = () => useContext(RequiredLabelContext);

/**
 * Step registry — a `FormRenderer.Step` provides this so the fields rendered inside it can
 * register their `name`, and the stepper validates just those names before advancing. `null`
 * when not inside a stepper.
 *
 * The stepper itself lives in `FormRenderer` — it is chrome. This registry stays here because
 * the *fields* are what register into it (see `fields/FieldShell.tsx`), and FormBuilder must
 * stand alone without FormRenderer installed. FormRenderer's `StepSlot` imports it from here;
 * the dependency never points the other way.
 */
export interface StepRegistry {
  register: (name: string) => void;
  unregister: (name: string) => void;
}
export const StepContext = createContext<StepRegistry | null>(null);
export const useStepRegistry = () => useContext(StepContext);

import React from "react";
import type { FieldKind } from "./types";

/**
 * The stamp that tells a consumer what a `FormBuilder.*` field produces.
 *
 * A form is normally read by the resolver and the submit handler, both of which know the shape
 * they expect. Some consumers do not: `DataViews.Filters` is handed arbitrary fields as children
 * and has to turn each one's value into a filter — a list, a numeric range, a date range — without
 * being told which is which.
 *
 * The alternative is comparing `element.type` against an imported component, which breaks across
 * duplicated module instances and silently stops matching after a hot reload. A property on the
 * component survives both.
 */

const KEY = "__fieldKind";

export function markFieldKind<T>(component: T, kind: FieldKind): T {
  (component as Record<string, unknown>)[KEY] = kind;
  return component;
}

/** The kind stamped on an element's component, or `undefined` if it is not a marked field. */
export function fieldKindOf(node: React.ReactNode): FieldKind | undefined {
  if (!React.isValidElement(node)) return undefined;
  return (node.type as unknown as Record<string, unknown> | undefined)?.[KEY] as FieldKind | undefined;
}

"use client";

import { LabeledCheckBox } from "../../LabeledCheckBox";
import { RadioGroup } from "../../Radio";
import { RadioCard } from "../../RadioCard";
import { useLoading } from "../context";
import type { CheckboxFieldProps, RadioCardsFieldProps } from "../types";
import { FieldShell } from "./FieldShell";

/**
 * `FormBuilder.Checkbox` — a single boolean checkbox. The field `label` sits in the
 * normal label column; an optional `subLabel` renders inline beside the checkbox (via
 * the clickable `LabeledCheckBox`).
 */
export function CheckboxField({ subLabel, ...props }: CheckboxFieldProps) {
  const loading = useLoading();
  return (
    <FieldShell {...props}>
      {(field) => (
        <div className="flex w-full items-center ps-2.5">
          <LabeledCheckBox
            id={props.name}
            label={subLabel ?? ""}
            checked={!!field.value}
            size="S"
            onCheckedChange={(checked) => field.onChange(checked === true)}
            disabled={props.disabled || loading}
          />
        </div>
      )}
    </FieldShell>
  );
}

/** `FormBuilder.RadioCards` — radio options rendered as cards (Glare `RadioCard`). */
export function RadioCardsField(props: RadioCardsFieldProps) {
  const loading = useLoading();
  return (
    <FieldShell {...props}>
      {(field) => (
        <RadioGroup
          value={field.value ?? ""}
          onValueChange={field.onChange}
          className="grid w-full grid-cols-2 gap-3"
        >
          {props.options.map((opt) => (
            <RadioCard
              key={opt.value}
              id={`${props.name}-${opt.value}`}
              value={opt.value}
              headerLabel={opt.label}
              description={opt.description}
              disabled={opt.disabled || props.disabled || loading}
            />
          ))}
        </RadioGroup>
      )}
    </FieldShell>
  );
}

"use client";

import { InputField } from "../../InputField";
import { ColorPicker, CHECKERBOARD } from "../../ColorPicker";
import { useLoading } from "../context";
import type { ColorFieldProps } from "../types";
import { FieldShell } from "./FieldShell";

/**
 * `FormBuilder.Color` — an `InputField` holding the hex text, with a trailing action button that
 * carries the colour itself. That button is the `ColorPicker` trigger: clicking it opens the full
 * palette. Value is a hex string.
 */
export function ColorField(props: ColorFieldProps) {
  const loading = useLoading();

  return (
    <FieldShell {...props}>
      {(field) => {
        const value = typeof field.value === "string" ? field.value : "";
        const disabled = props.disabled || loading;
        return (
          // The InputField IS the trigger: ColorPicker detects it as an input (it takes a `value`)
          // and feeds it the hex, so clicking the field opens the palette.
          <ColorPicker
            value={value || undefined}
            onChange={field.onChange}
            presets={props.presets}
            alpha={props.alpha ?? true}
            disabled={disabled}
          >
            <InputField
              // Explicit — otherwise Radix's trigger `type="button"` would land on the input.
              type="text"
              value={value}
              onChange={(e) => field.onChange(e.target.value)}
              placeholder={props.placeholder ?? "#000000"}
              disabled={disabled}
              className="w-full"
              // The trailing action button holds the colour itself.
              childrenSide={
                <span
                  aria-hidden
                  className="block h-[26px] w-[26px] shrink-0 overflow-hidden rounded-[6px] border border-border-presentation-action-primary"
                  style={CHECKERBOARD}
                >
                  <span
                    className="block h-full w-full"
                    style={{ backgroundColor: value || "#000000" }}
                  />
                </span>
              }
            />
          </ColorPicker>
        );
      }}
    </FieldShell>
  );
}

"use client";

import type { CustomFieldProps } from "../types";
import { FieldShell } from "./FieldShell";

/** `FormBuilder.Custom` — render any control, keeping the FieldSection + validation wiring. */
export function CustomField(props: CustomFieldProps) {
  return (
    <FieldShell {...props}>{(field, fieldState) => props.render({ field, fieldState })}</FieldShell>
  );
}

"use client";

import { DatePicker } from "../../DatePicker";
import { useOnTable } from "../context";
import type { DateFieldProps } from "../types";
import { FieldShell } from "./FieldShell";

/**
 * `FormBuilder.Date` (single) — and, via `mode`/`timePicker`, the presets
 * `.DateRange` (value `{from,to}`), `.DateMultiple` (value `Date[]`), and
 * `.DateTime` (date + time). All back onto the one Glare `DatePicker`.
 */
export function DateField(props: DateFieldProps) {
  const onTable = useOnTable();

  return (
    <FieldShell {...props}>
      {(field) => (
        <DatePicker
          mode={props.mode ?? "single"}
          timePicker={props.timePicker}
          dateFormat={props.dateFormat}
          value={field.value}
          onTable={onTable}
          onChange={(e) =>
            field.onChange((e as unknown as { target: { value: unknown } }).target.value)
          }
        />
      )}
    </FieldShell>
  );
}

"use client";

import { useFormContext, useFieldArray, type FieldValues, type ArrayPath } from "react-hook-form";

import { Button } from "../../Button";
import { Card } from "../../Card";
import type { FieldArrayProps } from "../types";

/**
 * `FormBuilder.FieldArray` — a repeating list of sub-fields (RHF `useFieldArray`).
 * `children` renders one row's fields; name them `${rowName}.field`.
 */
export function FieldArray(props: FieldArrayProps) {
  const form = useFormContext<FieldValues>();
  const { fields, append, remove } = useFieldArray({
    control: form.control,
    name: props.name as ArrayPath<FieldValues>,
  });

  if (props.hidden) return null;

  const addButton = (
    <Button
      type="button"
      size="S"
      variant="BorderStyle"
      onClick={() => append((props.defaultItem ?? {}) as never)}
    >
      <i className="ri-add-line" />
      {props.addLabel ?? "Add"}
    </Button>
  );

  return (
    <section className="grid w-full max-w-[1200px] gap-3 px-[12px] py-[16px]">
      <div className="flex items-center justify-between">
        {props.label ? (
          <span className="typography-body-medium-medium text-content-presentation-global-primary">
            {props.label}
          </span>
        ) : (
          <span />
        )}
        {addButton}
      </div>
      {props.description && (
        <p className="typography-body-small-regular text-content-presentation-global-secondary">
          {props.description}
        </p>
      )}

      <div className="flex flex-col gap-3">
        {fields.map((f, index) => (
          <Card key={f.id} className="relative gap-3 pr-8">
            <button
              type="button"
              aria-label="Remove"
              onClick={() => remove(index)}
              className="absolute right-2 top-2 inline-flex h-[22px] w-[22px] items-center justify-center rounded-full text-content-presentation-state-negative transition-colors hover:bg-background-presentation-action-hover"
            >
              <i className="ri-close-line text-[16px]" />
            </button>
            {props.children(`${props.name}.${index}`, index, () => remove(index))}
          </Card>
        ))}
        {fields.length === 0 && (
          <p className="typography-body-small-regular text-content-presentation-global-secondary">
            No items yet.
          </p>
        )}
      </div>
    </section>
  );
}

"use client";

import { ReactNode, useEffect } from "react";
import {
  useFormContext,
  useFormState,
  type ControllerRenderProps,
  type ControllerFieldState,
  type FieldErrors,
  type FieldValues,
  type FieldPath,
} from "react-hook-form";

import { FieldSection } from "../../../layouts/FieldSection";
import { FormField, FormItem, FormControl } from "../../Form";
import { FieldHint } from "../../FieldHint";
import { useDirection, useStepRegistry, useBare, useRequiredLabel } from "../context";
import type { FieldHintSpec } from "../types";

export interface FieldShellProps {
  name: string;
  label?: ReactNode;
  description?: ReactNode;
  required?: boolean;
  fullWidth?: boolean;
  hidden?: boolean;
  /** Force the field's layout direction, overriding the form's `useDirection()` context. */
  direction?: "horizontal" | "vertical" | "flexible";
  /** Alerts stacked under the validation error. See `FieldHintSpec`. */
  hints?: FieldHintSpec[];
  /** The input, wired to the react-hook-form field. */
  children: (
    field: ControllerRenderProps<FieldValues, string>,
    fieldState: ControllerFieldState,
  ) => ReactNode;
}

/**
 * Shared wrapper for every `FormBuilder.*` field: the FieldSection row + the RHF
 * `FormField`/`FormItem`/`FormControl`/`FormMessage` scaffolding. Also registers the
 * field name into the enclosing `FormRenderer.Step` (if any) so the stepper can
 * validate per step.
 */
export function FieldShell({
  name,
  label,
  description,
  required,
  fullWidth,
  hidden,
  direction: directionProp,
  hints,
  children,
}: FieldShellProps) {
  const form = useFormContext();
  const bare = useBare();
  const ctxDirection = useDirection();
  // LOCAL PATCH (Contact Center): upstream hardcodes "(Required)". See context.ts.
  const requiredLabel = useRequiredLabel();
  // A field may pin its own direction (e.g. RichText forces vertical), else the form's. When
  // neither is set this stays `undefined` — FieldSection then falls back to its responsive
  // `flexible` layout rather than a fixed two-column one.
  const direction = directionProp ?? ctxDirection;
  const step = useStepRegistry();

  // Read this field's error at the shell level (not inside the FormField render) so
  // the FieldHint can go in FieldSection's `childrenUnderLabel` — under the label.
  // Subscribe to the whole `errors` object and resolve the field's path ourselves:
  // `getFieldState(name)` misses controls that register late (DatePicker, RichText),
  // whereas the errors object always carries every failing key from the resolver.
  const { errors } = useFormState({ control: form.control });
  const fieldError = resolveFieldError(errors, name);

  useEffect(() => {
    if (!step) return;
    step.register(name);
    return () => step.unregister(name);
  }, [step, name]);

  if (hidden) return null;

  // Chrome-less mode — a `FormBuilder.Table` cell (`"table"`) or a panel field (`"bare"`).
  // Render just the control: no FieldSection label/row, so a row stays one line tall. Step
  // registration above still applies. The control's border treatment is the caller's call,
  // via `useOnTable`.
  //
  // LOCAL PATCH (Contact Center): the error Tooltip that used to wrap the control is gone.
  // Upstream bound it to `open={Boolean(fieldError)}`, so it was not a hover tooltip at all — it
  // was a bubble pinned open for as long as the field was invalid, anchored `top`, which in a
  // table's first row sat directly on top of the column header. Several invalid cells meant
  // several permanent bubbles over the header row. Its `TooltipTrigger` also stamped
  // `aria-label="Open tooltip"` onto EVERY cell wrapper, error or not, so a screen reader
  // announced every table input that way.
  //
  // The controls already signal invalidity themselves (`state="negative"` / `invalid`), so the
  // red border remains; only the bubble is dropped. Re-apply after any `npx torch-glare update`.
  if (bare) {
    return (
      <FormField
        control={form.control}
        name={name as FieldPath<FieldValues>}
        render={({ field, fieldState }) => (
          <FormItem className="w-full">
            <FormControl>
              <div className="w-full">{children(field, fieldState)}</div>
            </FormControl>
          </FormItem>
        )}
      />
    );
  }

  return (
    <FieldSection
      label={label}
      requiredLabel={required ? requiredLabel : undefined}
      secondaryLabel={description}
      direction={direction}
      className={fullWidth ? "max-w-full" : undefined}
      childrenUnderLabel={<FieldMessages message={fieldError} hints={hints} />}
    >
      <FormField
        control={form.control}
        name={name as FieldPath<FieldValues>}
        render={({ field, fieldState }) => (
          <FormItem className="w-full">
            <FormControl>
              <div className="w-full">{children(field, fieldState)}</div>
            </FormControl>
          </FormItem>
        )}
      />
    </FieldSection>
  );
}

/**
 * The stack under a field: the validation error first (it is the actionable one), then any author
 * `hints` in order. Renders nothing when there is neither, so a field without hints is unchanged.
 */
function FieldMessages({ message, hints }: { message?: string; hints?: FieldHintSpec[] }) {
  if (!message && !hints?.length) return null;
  return (
    <div className="flex flex-col items-start gap-[4px]">
      {message && <FieldHint state="error" label={message} />}
      {hints?.map((hint, i) => (
        <FieldHint key={i} state={hint.state ?? "info"} label={hint.label} icon={hint.icon} />
      ))}
    </div>
  );
}

/**
 * Resolve a field's error message from the RHF `errors` tree by its dotted `name`
 * (handles nested field-array paths like `contacts.0.email`). Reading the errors
 * object directly is more reliable than `getFieldState` for controls that register
 * late (DatePicker, RichText), whose hints were otherwise missing.
 */
function resolveFieldError(errors: FieldErrors, name: string): string | undefined {
  const node = name
    .split(".")
    .reduce<unknown>(
      (acc, key) => (acc == null ? undefined : (acc as Record<string, unknown>)[key]),
      errors,
    );
  const message = (node as { message?: unknown } | undefined)?.message;
  return typeof message === "string" ? message : undefined;
}

"use client";

import { ImageAttachment } from "../../ImageAttachment";
import { useLoading } from "../context";
import type { FileFieldProps } from "../types";
import { FieldShell } from "./FieldShell";

/** `FormBuilder.File` / `.Image` — stores the selected `File` (consumer uploads). */
export function FileField(props: FileFieldProps & { image?: boolean }) {
  const loading = useLoading();
  return (
    <FieldShell {...props}>
      {(field) => {
        const current: unknown = field.value;
        const fileName = Array.isArray(current)
          ? `${current.length} file(s)`
          : current instanceof File
            ? current.name
            : "";
        return (
          <ImageAttachment
            mainLabel={props.placeholder ?? (props.image ? "Upload image" : "Upload file")}
            secondaryLabel={
              fileName || (typeof props.description === "string" ? props.description : "")
            }
            accept={props.accept ?? (props.image ? "image/*" : undefined)}
            multiple={props.multiple}
            disabled={props.disabled || loading}
            onChange={(e) => {
              const files = (e.target as HTMLInputElement).files;
              if (!files || files.length === 0) return;
              field.onChange(props.multiple ? Array.from(files) : files[0]);
            }}
          />
        );
      }}
    </FieldShell>
  );
}

"use client";

import { ReactNode } from "react";

import { cn } from "../../../utils/cn";
import { Label } from "../../Label";
import { RadioGroup, Radio } from "../../Radio";
import { Checkbox } from "../../Checkbox";
import { useLoading } from "../context";
import type { OptionItem, OptionsFieldProps } from "../types";
import { FieldShell } from "./FieldShell";

/**
 * The `#f9f9f9` rounded box that holds the option rows, with a full-width divider
 * between each (design nodes 8999:170512 / 8999:170546).
 */
function OptionBox({ children }: { children: ReactNode }) {
  return (
    <div
      className={cn(
        "flex w-full flex-col rounded-[8px] px-[10px]",
        "bg-background-presentation-form-field-primary",
        "divide-y divide-border-presentation-global-primary",
      )}
    >
      {children}
    </div>
  );
}

/**
 * One option row: control on the **left**, then the primary label and an optional
 * secondary label. Uses the `Label` component so the row is a real `<label>` — the
 * whole row is clickable and toggles the control (same mechanism as `LabeledCheckBox`
 * / `LabeledRadio`). `w-full` makes the entire row width tappable; `reverseChildren`
 * puts the control first (left) and `justify-end` keeps the content left-packed.
 */
function OptionRow({
  control,
  label,
  description,
}: {
  control: ReactNode;
  label?: string;
  description?: string;
}) {
  return (
    <Label
      label={label}
      secondaryLabel={description}
      labelDirections="horizontal"
      childrenDirections="horizontal"
      reverseChildren
      className="w-full cursor-pointer justify-end gap-[6px] py-[8px]"
    >
      {control}
    </Label>
  );
}

/**
 * `FormBuilder.RadioList` — single-select options (`string`) as a boxed, divided list
 * (design nodes 8999:170512). Uses the Radix `RadioGroup` for roving-focus / arrow-key nav.
 */
export function RadioListField(props: OptionsFieldProps) {
  const loading = useLoading();
  return (
    <FieldShell {...props}>
      {(field) => (
        <RadioGroup value={field.value ?? ""} onValueChange={field.onChange} className="w-full">
          <OptionBox>
            {props.options.map((opt: OptionItem) => (
              <OptionRow
                key={opt.value}
                label={opt.label}
                description={opt.description}
                control={
                  <Radio
                    id={`${props.name}-${opt.value}`}
                    value={opt.value}
                    size="S"
                    disabled={props.disabled || loading}
                  />
                }
              />
            ))}
          </OptionBox>
        </RadioGroup>
      )}
    </FieldShell>
  );
}

/**
 * `FormBuilder.CheckboxGroup` — multi-select options as a boxed, divided list (design
 * node 8999:170546). Value is a `string[]` of the selected option values.
 */
export function CheckboxGroupField(props: OptionsFieldProps) {
  const loading = useLoading();
  return (
    <FieldShell {...props}>
      {(field) => {
        const selected: string[] = Array.isArray(field.value) ? field.value : [];
        const toggle = (value: string, checked: boolean) => {
          field.onChange(checked ? [...selected, value] : selected.filter((v) => v !== value));
        };
        return (
          <div role="group" aria-label={typeof props.label === "string" ? props.label : undefined}>
            <OptionBox>
              {props.options.map((opt: OptionItem) => (
                <OptionRow
                  key={opt.value}
                  label={opt.label}
                  description={opt.description}
                  control={
                    <Checkbox
                      id={`${props.name}-${opt.value}`}
                      size="S"
                      checked={selected.includes(opt.value)}
                      onCheckedChange={(checked) => toggle(opt.value, checked === true)}
                      disabled={props.disabled || loading}
                    />
                  }
                />
              ))}
            </OptionBox>
          </div>
        );
      }}
    </FieldShell>
  );
}

"use client";

import { InputOTP, InputOTPGroup, InputOTPSlot } from "../../InputOTP";
import { useLoading } from "../context";
import type { OtpFieldProps } from "../types";
import { FieldShell } from "./FieldShell";

/** `FormBuilder.Otp` — a code / PIN input (Glare `InputOTP`). Value is a string. */
export function OtpField(props: OtpFieldProps) {
  const loading = useLoading();
  const length = props.length ?? 6;

  return (
    <FieldShell {...props}>
      {(field) => (
        <InputOTP
          maxLength={length}
          value={field.value ?? ""}
          onChange={(v: string) => field.onChange(v)}
          disabled={props.disabled || loading}
        >
          <InputOTPGroup>
            {Array.from({ length }, (_, i) => (
              <InputOTPSlot key={i} index={i} />
            ))}
          </InputOTPGroup>
        </InputOTP>
      )}
    </FieldShell>
  );
}

"use client";

import { SearchableSelect } from "../../SearchableSelect";
import { InputField } from "../../InputField";
import { cn } from "../../../utils/cn";
import { useLoading, useBare, useOnTable } from "../context";
import type { PhoneFieldProps } from "../types";
import { FieldShell } from "./FieldShell";
import { COUNTRIES, countryByCode, countryByDial, flagEmoji } from "./countries";

// Dial codes longest-first, so "+1" doesn't shadow "+1…"-style codes when prefix-matching.
const DIALS = [...new Set(COUNTRIES.map((c) => c.dial))].sort((a, b) => b.length - a.length);

// Country picker rows. Keyed by the unique ISO code; the row shows flag + dial, but `searchText`
// makes filtering match the country NAME (typing a dial code won't match).
const COUNTRY_OPTIONS = COUNTRIES.map((c) => ({
  value: c.code,
  label: `${flagEmoji(c.code)} ${c.dial}`,
  searchText: c.name,
}));

function splitPhone(value: unknown, defaultDial: string): { dial: string; number: string } {
  const s = typeof value === "string" ? value.trim() : "";
  if (!s) return { dial: defaultDial, number: "" };
  const idx = s.indexOf(" ");
  if (s.startsWith("+") && idx > 0) {
    return { dial: s.slice(0, idx), number: s.slice(idx + 1).trim() };
  }
  if (s.startsWith("+")) {
    const dial = DIALS.find((d) => s.startsWith(d));
    if (dial) return { dial, number: s.slice(dial.length).trim() };
  }
  return { dial: defaultDial, number: s };
}

/**
 * `FormBuilder.Phone` — country dial-code (every country) + number. The picker is a
 * `SearchableSelect` keyed by the unique ISO code (dial codes repeat) — type to filter by
 * country name or dial. The value is stored as a `"+<dial> <number>"` string.
 *
 * **Inside a `FormBuilder.Table` cell** this collapses to a single plain number input: the
 * fixed-width picker imposed a ~155px floor on the column and left the number truncated,
 * and two controls in one cell is not a table column. Add a separate column (e.g. a
 * `FormBuilder.Select` of dial codes) when a table needs the country code.
 */
export function PhoneField(props: PhoneFieldProps) {
  const loading = useLoading();
  // Neither a table cell nor a narrow config rail has room for the dial-code composite, so both
  // collapse to a single tel input — but only a real table cell takes the flush border.
  const bare = useBare();
  const onTable = useOnTable();
  const defaultDial = props.defaultCountry ?? "+964"; // Iraq

  if (bare) {
    return (
      <FieldShell {...props}>
        {(field) => (
          <InputField
            type="tel"
            inputMode="tel"
            value={typeof field.value === "string" ? field.value : ""}
            onChange={(e) => field.onChange(e.target.value.replace(/[^\d\s+-]/g, ""))}
            onBlur={field.onBlur}
            placeholder={props.placeholder ?? "Phone number"}
            disabled={props.disabled || loading}
            onTable={onTable}
            className="w-full"
          />
        )}
      </FieldShell>
    );
  }

  return (
    <FieldShell {...props}>
      {(field) => {
        const { dial, number } = splitPhone(field.value, defaultDial);
        const country = countryByDial(dial);
        const disabled = props.disabled || loading;
        const commit = (d: string, n: string) => field.onChange(n ? `${d} ${n}` : d);
        return (
          <div className="flex w-full min-w-0 items-center gap-2">
            {/* Searchable country picker — filter by name or dial; rows carry the full country name. */}
            <SearchableSelect
              options={COUNTRY_OPTIONS}
              value={country?.code ?? null}
              onValueChange={(code) => commit(countryByCode(code)?.dial ?? dial, number)}
              placeholder="+964"
              size="M"
              inputClassName="w-[100px] min-w-[0px]"
              className={cn("w-[113px] shrink-0", disabled && "pointer-events-none opacity-60")}
            />
            <div className="min-w-0 flex-1">
              <InputField
                type="tel"
                inputMode="tel"
                value={number}
                onChange={(e) => commit(dial, e.target.value.replace(/[^\d\s-]/g, ""))}
                placeholder={props.placeholder ?? "Phone number"}
                disabled={disabled}
                className="w-full"
              />
            </div>
          </div>
        );
      }}
    </FieldShell>
  );
}

