const nf = new Intl.NumberFormat("en-US", { maximumFractionDigits: 20 });

/** Format a number with thousands separators (e.g. 1299 → "1,299"). Blank for empty. */
export function formatNumber(value: unknown): string {
  if (value == null || value === "") return "";
  const n = typeof value === "number" ? value : Number(String(value).replace(/,/g, ""));
  return Number.isNaN(n) ? "" : nf.format(n);
}

/** Parse a possibly comma-formatted string to a number (or undefined when blank). */
export function parseNumber(raw: string): number | undefined {
  const cleaned = raw.replace(/,/g, "").trim();
  if (cleaned === "" || cleaned === "-" || cleaned === ".") return undefined;
  const n = Number(cleaned);
  return Number.isNaN(n) ? undefined : n;
}

"use client";

import { ReactNode } from "react";

import { cn } from "../../utils/cn";
import { Button } from "../Button";
import { useFormId, useLoading } from "./context";

export interface SubmitButtonProps {
  children?: ReactNode;
  className?: string;
  loadingText?: ReactNode;
  /**
   * The form to submit, by `id`. Defaults to the enclosing FormBuilder's own form id (via
   * context), so a bare `<FormBuilder.Submit>` works even in a header / action bar rendered
   * **outside** the `<form>` element. Set it explicitly only to target a different form.
   */
  form?: string;
  /**
   * LOCAL PATCH (Contact Center): upstream removed this in 2.5.5, leaving no way to
   * disable a Save. Re-apply after any `npx torch-glare update`.
   *
   * Disable the button while leaving the form readable.
   *
   * Used by permission gating: someone with read access should still SEE a
   * record, so a Save they may not use is disabled rather than removed --
   * a missing button looks broken, a disabled one says "not yours to change".
   * The server refuses the write either way.
   */
  disabled?: boolean;
}

/** `FormBuilder.Submit` — a loading-aware submit button, hidden in view mode. */
export function SubmitButton({
  children,
  className,
  loadingText,
  form,
  disabled,
}: SubmitButtonProps) {
  const loading = useLoading();
  const ctxFormId = useFormId();

  return (
    <Button
      type="submit"
      // Defaults to the enclosing form's id, so a Save in the header (outside the `<form>`)
      // still submits it via native form-association.
      form={form ?? ctxFormId}
      // The blue fill, because Save is the form's primary action and a primary action is blue.
      // Deliberately not a prop: a form has one primary action, and letting each caller pick a
      // variant is how the rule stops being a rule.
      variant="BluColStyle"
      is_loading={loading}
      // LOCAL PATCH (Contact Center) -- see `disabled` in SubmitButtonProps.
      disabled={disabled}
      // `w-fit` because the FormBuilder root is a flex COLUMN: a direct child with `width: auto`
      // inherits `align-items: stretch` and spans the whole form. Sections want that (SectionBlock
      // sets its own `w-full`); a Save button does not. `w-fit` rather than `self-start` so the
      // header action bar — a row with `items-center` — is untouched at every button size.
      // Merged through `cn` so a caller can still opt into `className="w-full"` in a narrow drawer.
      className={cn("w-fit", className)}
    >
      {loading ? (loadingText ?? children ?? "Saving…") : (children ?? "Save")}
    </Button>
  );
}

import { ReactNode } from "react";
import type {
  ControllerRenderProps,
  ControllerFieldState,
  DefaultValues,
  FieldErrors,
  FieldValues,
  Resolver,
  UseFormReturn,
} from "react-hook-form";
import type { FieldDirection } from "./context";
import type { SectionColor } from "../SectionBlock";

/**
 * What shape of value a field produces, stamped on each `FormBuilder.*` field component.
 *
 * This is for consumers that have to interpret a form they did not author — `DataViews.Filters`
 * reads it to decide whether a child's value becomes a list, a numeric range or a date range. It
 * describes the field, not any one consumer's use of it.
 *
 * Read it with `fieldKindOf(element)` rather than comparing `element.type` against an imported
 * component: identity comparison breaks across duplicated module instances and stops matching
 * after a hot reload.
 */
export type FieldKind =
  /** A string value — `Text`, `Textarea`, `Email`, `Password`, `Color`, `Phone`, `Otp`. */
  | "text"
  /** A number — `Number`, `Currency`. */
  | "number"
  /** One of a supplied list — `Select`, `SearchableSelect`, `RadioList`, `RadioCards`. */
  | "choice"
  /** Several of a supplied list — `MultiSelect`, `Tags`, `CheckboxGroup`, `TreeSelect`. */
  | "multiChoice"
  /** A boolean — `Checkbox`, `SwitchBox`. */
  | "boolean"
  /** A date or date range — `Date`, `DateRange`, `DateTime`, `DateMultiple`. */
  | "date"
  /** Two numbers when `range`, otherwise one — `Slider`. */
  | "slider"
  /** Whatever the caller renders — `Custom`, `File`, `Image`, `Signature`, `RichText`. */
  | "custom";

/** Props shared by every `FormBuilder.*` field. `name` is the RHF path. */
/**
 * One alert under a field. Mirrors `FieldHint`'s own props so the design system stays the single
 * source of truth for how each state looks.
 */
export interface FieldHintSpec {
  label: ReactNode;
  state?: "info" | "warning" | "error" | "success";
  icon?: ReactNode;
}

export interface BaseFieldProps {
  name: string;
  label?: ReactNode;
  placeholder?: string;
  description?: ReactNode;
  required?: boolean;
  disabled?: boolean;
  hidden?: boolean;
  /** Span the full section width. */
  fullWidth?: boolean;
  /**
   * Alerts stacked under the field. The validation error, when there is one, always renders first —
   * it is the actionable message — and these follow in order. Ignored in `bare` mode (a
   * `FormBuilder.Table` cell), where errors surface as a tooltip to keep the row one line tall.
   */
  hints?: FieldHintSpec[];
}

export interface OptionItem {
  label: string;
  value: string;
  icon?: ReactNode;
  /** Secondary row label — shown by `FormBuilder.RadioList` / `.CheckboxGroup`. */
  description?: string;
}

/** `FormBuilder.Select` / `.SearchableSelect` — supports async option loading. */
/** `FormBuilder.Select` — the plain `Select` dropdown. */
export interface SelectFieldProps extends BaseFieldProps {
  options: OptionItem[];
}

/**
 * `FormBuilder.SearchableSelect` — the `SearchableSelect` combobox: a search box with
 * client-side filtering, or server-side search + infinite scroll via the async props.
 */
export interface SearchableSelectFieldProps extends SelectFieldProps {
  /** Filter `options` locally (default). Set false for server-side search. */
  filterClientSide?: boolean;
  /** Debounced as the user types — refetch your data here. */
  onSearchChange?: (query: string) => void;
  /** Called when the list bottom scrolls into view and `hasMore && !loading`. */
  onLoadMore?: () => void;
  hasMore?: boolean;
  loading?: boolean;
}

/** `FormBuilder.MultiSelect` / `.Tags`, `.Radio`. */
export interface OptionsFieldProps extends BaseFieldProps {
  options: OptionItem[];
  /**
   * LOCAL PATCH (Contact Center): `MultiSelect`/`Tags` only — let the user type a value that is
   * not in `options` and have it become a badge. Pass `options={[]}` for a pure free-text list.
   */
  creatable?: boolean;
}

/** `FormBuilder.Currency`. */
export interface CurrencyFieldProps extends BaseFieldProps {
  currencySymbol?: ReactNode;
}

/** `FormBuilder.File` / `.Image`. */
export interface FileFieldProps extends BaseFieldProps {
  accept?: string;
  multiple?: boolean;
}

/** `FormBuilder.Custom` — bring your own control, keeping the FieldSection + validation wiring. */
